const $=id=>document.getElementById(id),audio=$('audio');let url,rate=.9,target=.9,ramp=null,sequence=null,mode='live',last=performance.now();
const presets=[['Quiet Exploration',85,100,4,'Gentle movement for an unhurried scene.'],['Unease',90,110,8,'A restrained rise with a lingering sense of tension.'],['Threat Approaching',90,120,10,'A gradual climb toward danger.'],['Pursuit',100,130,2,'Quick acceleration for a scene in motion.'],['Panic',110,140,.6,'A fast, controlled rise in urgency.'],['Relief',80,100,12,'A soft descent after the action.'],['Dream / Distortion',70,110,6,'Tape-style motion: pitch follows playback speed.']].map(([name,low,high,ramp,description])=>({name,low,high,ramp,description,pitch:name!=='Dream / Distortion'}));
let saved=[];try{saved=JSON.parse(localStorage.getItem('pulse-presets')||'[]');if(!Array.isArray(saved))saved=[]}catch{};presets.push(...saved);
function options(){ $('preset').replaceChildren(...presets.map((p,i)=>new Option(p.name,i))); }options();
function number(id,min,max,fallback){let n=Number($(id).value);if(!Number.isFinite(n))n=fallback;n=Math.max(min,Math.min(max,n));$(id).value=n;return n}
function bounds(){let lo=number('low',50,200,85),hi=number('high',50,200,100);if(hi<lo){hi=lo;$('high').value=hi}return [lo/100,hi/100]}
function map(v){let [lo,hi]=bounds();return lo+(hi-lo)*v}
function ease(t){return $('shape').value==='linear'?t:t*t*(3-2*t)}
function aim(v,instant=false){target=v;ramp=instant?null:{from:rate,to:v,t:0,d:Number($('ramp').value)};if(instant)rate=v}
function liveTarget(){aim(map(Number($('intensity').value)/100))}
function hold(){sequence=null;ramp=null;target=rate;$('cancel').disabled=true}
function switchMode(m){hold();mode=m;$('live').classList.toggle('hidden',m!=='live');$('sequence').classList.toggle('hidden',m!=='seq');$('liveTab').classList.toggle('active',m==='live');$('seqTab').classList.toggle('active',m==='seq');let [lo,hi]=bounds();$('intensity').value=hi===lo?0:Math.max(0,Math.min(100,(rate-lo)/(hi-lo)*100));}
$('liveTab').onclick=()=>switchMode('live');$('seqTab').onclick=()=>switchMode('seq');
function apply(){hold();const p=presets[$('preset').value];for(const id of ['low','high','ramp'])$(id).value=p[id];$('pitch').checked=p.pitch;$('description').textContent=p.description||'Your saved musical direction.';if(p.seq)$('seq').value=p.seq;if(p.duration)$('duration').value=p.duration;if(p.shape)$('shape').value=p.shape;if(p.intensity!=null)$('intensity').value=p.intensity;if(p.fall)$('fall').value=p.fall;if(p.align)$('align').value=p.align;audio.preservesPitch=p.pitch;if(p.cues&&typeof drawCues==='function'){cues=p.cues.map(c=>({...c}));drawCues()}draw();liveTarget()}
$('preset').onchange=apply;$('intensity').oninput=()=>{hold();liveTarget()};$('calm').onclick=()=>{$('intensity').value=0;liveTarget()};for(const id of ['low','high'])$(id).onchange=()=>{hold();liveTarget()};$('base').onchange=()=>number('base',30,300,100);$('ramp').oninput=()=>{$('rampValue').textContent=$('ramp').value;if(ramp)aim(target)};$('pitch').onchange=()=>audio.preservesPitch=$('pitch').checked;$('loop').onchange=()=>audio.loop=$('loop').checked;$('volume').oninput=()=>audio.volume=Number($('volume').value);
function draw(){$('curvepath').setAttribute('d',$('seq').value==='build'?'M0 110 C220 110 380 20 600 20':$('seq').value==='settle'?'M0 20 C220 20 380 110 600 110':'M0 110 C70 110 90 20 150 20 L330 20 C450 20 470 110 600 110')}$('seq').onchange=()=>{hold();draw()};
async function play(){try{await audio.play();$('status').textContent='Playing · '+(mode==='live'?'live direction':'sequence mode')}catch{$('status').textContent='Playback failed. Try a PCM WAV file.'}}
$('play').onclick=()=>audio.paused?play():audio.pause();audio.onplay=()=>{last=performance.now();$('play').textContent='Pause'};audio.onpause=()=>$('play').textContent='Play';audio.onended=()=>{hold();$('status').textContent='Track finished.'};
$('stop').onclick=()=>{audio.pause();audio.currentTime=0;hold();$('cursor').setAttribute('x1',0);$('cursor').setAttribute('x2',0);$('status').textContent='Reset to the start.'};$('seek').oninput=()=>{if(Number.isFinite(audio.duration))audio.currentTime=audio.duration*Number($('seek').value)/100};
$('run').onclick=async()=>{let [lo,hi]=bounds();sequence={t:0,d:number('duration',2,300,20),from:rate,lo,hi,type:$('seq').value};ramp=null;$('cancel').disabled=false;await play()};$('cancel').onclick=()=>{hold();$('status').textContent='Holding current speed.'};
function load(blob,name){audio.pause();hold();if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(blob);audio.src=url;$('filename').textContent=name;$('play').disabled=$('stop').disabled=$('run').disabled=true;$('status').textContent='Loading audio…';audio.load()}
audio.onloadedmetadata=()=>{$('play').disabled=$('stop').disabled=$('run').disabled=false;$('status').textContent='Ready. Press Play or run a sequence.'};audio.onerror=()=>{$('status').textContent='This audio could not be decoded. Try a PCM WAV.'};$('file').onchange=e=>{if(e.target.files[0])load(e.target.files[0],e.target.files[0].name)};const drop=$('drop');drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');if(e.dataTransfer.files[0])load(e.dataTransfer.files[0],e.dataTransfer.files[0].name)};
$('demo').onclick=()=>{const sr=22050,seconds=9.6,n=Math.round(sr*seconds),b=new ArrayBuffer(44+n*2),v=new DataView(b);function str(o,s){for(let i=0;i<s.length;i++)v.setUint8(o+i,s.charCodeAt(i))}str(0,'RIFF');v.setUint32(4,36+n*2,true);str(8,'WAVEfmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,sr,true);v.setUint32(28,sr*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,n*2,true);for(let i=0;i<n;i++){let t=i/sr,beat=t%.6,sub=t%.3,notes=[130.81,155.56,196,233.08],f=notes[Math.floor(t/2.4)%4],env=Math.min(1,t/.02,(seconds-t)/.02);let a=.35*Math.sin(2*Math.PI*(48*beat+5*(1-Math.exp(-beat*35))))*Math.exp(-beat*14)+.13*Math.sin(2*Math.PI*f*t)*Math.exp(-sub*9)+.055*Math.sin(2*Math.PI*f/2*t);v.setInt16(44+i*2,Math.max(-1,Math.min(1,a*env))*32767,true)}$('base').value=100;load(new Blob([b],{type:'audio/wav'}),'Pulse study · 100 BPM · demo loop')};
$('save').onclick=()=>{const name=$('name').value.trim();if(!name){$('status').textContent='Give your preset a name first.';return}const [lo,hi]=bounds(),p={name,low:lo*100,high:hi*100,ramp:Number($('ramp').value),pitch:$('pitch').checked,fall:Number($('fall').value),align:$('align').value,shape:$('shape').value,seq:$('seq').value,duration:number('duration',2,300,20),intensity:Number($('intensity').value),cues:cues.map(c=>({...c}))};try{saved.push(p);localStorage.setItem('pulse-presets',JSON.stringify(saved));presets.push(p);options();$('preset').value=presets.length-1;$('status').textContent='Preset saved in this browser.'}catch{$('status').textContent='Browser storage unavailable; preset could not be saved.'}};
function clock(s){if(!Number.isFinite(s))return '0:00';return Math.floor(s/60)+':'+String(Math.floor(s%60)).padStart(2,'0')}
function tick(now){let dt=Math.max(0,(now-last)/1000);last=now;if(!audio.paused){if(window.sceneStep)window.sceneStep(dt);if(sequence){let s=sequence;s.t+=dt;let x=Math.min(1,s.t/s.d);if(s.type==='build')rate=s.from+(s.hi-s.from)*ease(x);else if(s.type==='settle')rate=s.from+(s.lo-s.from)*ease(x);else rate=x<.25?s.from+(s.hi-s.from)*ease(x/.25):x<.55?s.hi:s.hi+(s.lo-s.hi)*ease((x-.55)/.45);target=rate;$('cursor').setAttribute('x1',x*600);$('cursor').setAttribute('x2',x*600);if(x===1){hold();$('status').textContent='Sequence complete · holding final speed.'}}else if(ramp){ramp.t+=dt;let x=Math.max(0,Math.min(1,ramp.t/ramp.d));rate=ramp.from+(ramp.to-ramp.from)*ease(x);if(x===1)ramp=null}}audio.playbackRate=rate;$('bpm').textContent=Math.round(Number($('base').value)*rate);$('ratio').textContent=rate.toFixed(2)+'× speed';$('target').textContent='Target '+Math.round(Number($('base').value)*target)+' BPM';$('meter').style.width=((rate-.5)/1.5*100)+'%';$('intValue').textContent=$('intensity').value+'%';$('rampValue').textContent=$('ramp').value;$('time').textContent=clock(audio.currentTime)+' / '+clock(audio.duration);if(document.activeElement!==$('seek'))$('seek').value=audio.duration?audio.currentTime/audio.duration*100:0;setTimeout(()=>tick(performance.now()),20)}
audio.loop=true;audio.volume=.65;audio.preservesPitch=true;apply();requestAnimationFrame(tick);
